$p="$((Get-Location).Path)\public\pdfs";$o="$((Get-Location).Path)\src\content\works";if(!(Test-Path $o)){New-Item -ItemType Directory -Path $o -Force|Out-Null};Get-ChildItem $p -Filter "*.pdf"|ForEach-Object{$t=Join-Path $o ($_.BaseName+".md");if(!(Test-Path $t)){$c="---`ntitle: `""+$_.BaseName+"`"`ndescription: `""+$_.BaseName+" の記述`"`ncategory: `"creative`"`npdfUrl: `"/pdfs/"+$_.Name+"`"`npublishDate: 2026-08-29`n---`n";Set-Content -Path $t -Value $c -Encoding utf8;Write-Host "Created: "$_.Name}}
